import Foundation

struct AuraPlusEntitlement {
    static let productName = "com.yourcompany.aura.auraplus"

    // Entitlements provided by the 'Aura+' purchase
    let isWatermarkFree: Bool
    let hasExpandedPaletteLibrary: Bool
    let canRegenerateDaily: Bool

    init(isWatermarkFree: Bool, hasExpandedPaletteLibrary: Bool, canRegenerateDaily: Bool) {
        self.isWatermarkFree = isWatermarkFree
        self.hasExpandedPaletteLibrary = hasExpandedPaletteLibrary
        self.canRegenerateDaily = canRegenerateDaily
    }

    static func fromEntitlementSnapshot(_ snapshot: EntitlementSnapshot) -> AuraPlusEntitlement {
