import StoreKit

actor StoreManager {
    static let shared = StoreManager()

    private var transactionListenerTask: Task<Void, Never>?

    // Initialize the product and start listening for transactions
    func initialize() async throws {
        try await SKProduct.requestProductData(for: [AuraPlusEntitlement.productName]) { products, invalidIdentifiers in
            guard let product = products.first else {
                print("Failed to load product data")
                return
            }
            // Start listening for transactions
            self.startTransactionListener()
        }
    }

    private func startTransactionListener() {
        transactionListenerTask?.cancel()
        transactionListenerTask = Task {
            for await result in Transaction.updates {
                do {
                    let transaction = try result.confirm()
                    handle(transaction)
                } catch {
                    print("Failed to confirm transaction: \(error)")
                }
            }
        }
    }

    private func handle(_ transaction: Transaction) {
        // Update the entitlement snapshot based on the transaction
        let snapshot = EntitlementSnapshot(isAuraPlus: true, unlockedPaletteTier: .auraPlusExpanded, capturedAt: Date())
        updateEntitlement(snapshot)
    }

    func purchaseAuraPlus() async throws -> EntitlementSnapshot {
        guard let product = try await getProduct() else {
            throw NSError(domain: "Product not available", code: 0, userInfo: nil)
        }

        // Start the purchase
        let result = try await product.purchase()

        switch result {
        case .success(let verification):
            handle(verification.transaction)
            return EntitlementSnapshot(isAuraPlus: true, unlockedPaletteTier: .auraPlusExpanded, capturedAt: Date())
        case .pending:
            print("Purchase pending")
            return EntitlementSnapshot(isAuraPlus: false, unlockedPaletteTier: .freeBase, capturedAt: Date())
        case .userCancelled:
            print("User cancelled purchase")
            throw NSError(domain: "User cancelled", code: 0, userInfo: nil)
        @unknown default:
            fatalError("Unknown purchase result")
        }
    }

    func restorePurchases() async throws -> EntitlementSnapshot? {
        let result = try await Transaction.restore()

        switch result {
        case .success(let transactions):
            for transaction in transactions {
                handle(transaction)
            }
            return try await getLatestEntitlement()
        case .userCancelled:
            print("User cancelled restore")
            throw NSError(domain: "User cancelled", code: 0, userInfo: nil)
        @unknown default:
            fatalError("Unknown restore result")
        }
    }

    private func getProduct() async throws -> SKProduct? {
        let products = try await SKProduct.requestProductData(for: [AuraPlusEntitlement.productName])
        return products.first
    }

    private func updateEntitlement(_ snapshot: EntitlementSnapshot) {
        // Update the entitlement in AuraStore or wherever it's stored
        // This is a placeholder for actual implementation
        print("Updated entitlement to \(snapshot)")
    }

    private func getLatestEntitlement() async throws -> EntitlementSnapshot? {
        // Fetch the latest entitlement snapshot from storage
        // This is a placeholder for actual implementation
        return try await Task.sleep(nanoseconds: 1_000_000) // Simulate fetching from storage
            .flatMap { _ in
                return EntitlementSnapshot(isAuraPlus: true, unlockedPaletteTier: .auraPlusExpanded, capturedAt: Date())
            }
    }
}
```

